if(role==='teacher'){const data=await api('/rest/v1/rpc/my_teacher_dashboard','POST',{});db={teachers:[],students:[],sessions:[],payments:[],expenses:[],payroll:[],notices:[],absence_requests:[],...data};render();return;}
