let teacher=id=>db.teachers.find(t=>t.id===id)?.name?.replace(/فروقی/g,'فروغی')||'—',full=s=>s.first_name+' '+s.last_name,credit=s=>Number(s.opening_credit)+confirmedPayments().filter(p=>p.student_id===s.id).reduce((a,p)=>a+p.terms*4,0)-db.sessions.filter(c=>c.student_id===s.id&&['completed','absent'].includes(c.status)).length;
