function tag(s){return `<span class="badge ${eligible(s)?'':'red'}">${eligible(s)?'مجاز به حضور':'نیازمند پرداخت'}</span>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">هنوز اطلاعاتی ثبت نشده است</td></tr>`}</tbody></table></div>`}
function title(name,sub,action=''){return `<div class="title"><div><h1>${name}</h1><div class="sub">${sub}</div></div>${action}</div>`}function btn(s,f){return `<button class="primary" onclick="${f}">＋ ${s}</button>`}
