const views={myteaching(){const t=db.teachers.find(t=>t.id===currentTeacherId);if(!admin||!t)return '<div class="card empty">پرونده تدریس به این حساب متصل نیست.</div>';const list=db.students.filter(s=>s.teacher_id===currentTeacherId);return title('کلاس‌های من','دسترسی تدریس در کنار مدیریت آموزشگاه')+`<div class="card"><div class="teaching-header">${window.teacherInline?window.teacherInline(t.name):esc(t.name)}</div>${studentTable(list)}<p class="sub">جلسات ثبت‌شده این استاد: ${money(db.sessions.filter(c=>list.some(s=>s.id===c.student_id)).length)}</p></div>`},accounts(){return title('مدیریت دسترسی‌ها','اختصاص نقش به ایمیل تأییدشده',btn('اختصاص دسترسی','assignStaff()'))+`<div class="card policy"><h3>هر شخص، حساب و نقش اختصاصی</h3><p>مدیر و منشی تعیین‌شده فقط پس از تأیید ایمیل وارد نقش خود می‌شوند. برای اساتید، ایمیل و نام استاد مربوطه را ثبت کنید. کاربران دیگر تا اتصال پرونده هنرجو، به اطلاعات شخصی دسترسی ندارند.</p><p>منشی به سود، هزینه‌ها، حقوق و تنظیم نقش‌ها دسترسی ندارد. استاد فقط برنامه، نام هنرجویان و دستمزد خودش را می‌بیند.</p></div>`},login(){return title('پرتال آوای هزاردستان','ورود اختصاصی مدیر، منشی، اساتید و هنرجویان')+`<div class="card" style="max-width:620px;margin:35px auto;text-align:center;padding:38px"><img src="logo.png" style="width:130px;border-radius:18px" alt="لوگوی آموزشگاه"><h2>به خانه هنر خودتان خوش آمدید</h2><p class="policy">بار اول ایمیل را با کد تأیید کنید و رمز بسازید؛ دفعات بعد با ایمیل و رمز وارد شوید.</p><button class="primary" onclick="login()">ورود به پرتال</button><p><a href="index.html">بازگشت به سایت آموزشگاه ←</a></p></div>`},dashboard(){const income=confirmedPayments().reduce((a,p)=>a+Number(p.amount),0),out=db.expenses.reduce((a,p)=>a+Number(p.amount),0),salaries=db.sessions.reduce((a,s)=>a+Number(s.teacher_share||0),0);return title('هنر، با نظم زیباتر می‌شود.','یک نگاه به جریان امروز آموزشگاه',btn('ثبت هنرجوی جدید','newStudent()'))+`<div class="hero"><div><h2>به آوای هزاردستان خوش آمدید</h2><p>همه‌چیز برای یک روز هماهنگ؛ از اولین نت تا آخرین کلاس.</p></div><span class="note">♫</span></div><div class="stats">${[['هنرجویان',db.students.length,'هنرجوی ثبت‌شده'],['شهریه دریافتی',income,'تومان · پرداخت‌های ثبت‌شده'],['هزینه و دستمزد',out+salaries,'تومان · هزینه‌ها + جلسات برگزارشده'],['مانده عملیاتی',income-out-salaries,'تومان · دریافت منهای هزینه و دستمزد']].map(([s,n,f])=>`<div class="card"><div class="statlabel">${s}<span>◈</span></div><div class="statnum">${money(n)}</div><div class="statfoot">${f}</div></div>`).join('')}</div><div class="grid"><div class="card"><div class="cardhead"><h3>جریان مالی آموزشگاه</h3><span class="sub">${demo?'نمودار نمونه':'شش ماه اخیر'}</span></div><div class="chart">${Array.from({length:6},(_,i)=>{const date=new Date();date.setMonth(date.getMonth()-5+i);const filter=a=>a.filter(p=>new Date(p.created_at||p.expense_date).getMonth()===date.getMonth()&&new Date(p.created_at||p.expense_date).getFullYear()===date.getFullYear()).reduce((s,p)=>s+Number(p.amount),0);const amounts=[filter(confirmedPayments()),filter(db.expenses)];return `<div class="bars"><div class="bar" style="height:${demo?[40,65,48,80,61,92][i]:Math.min(95,amounts[0]/200000)}%"></div><div class="bar light" style="height:${demo?[22,32,28,40,33,45][i]:Math.min(95,amounts[1]/200000)}%"></div><label>${date.toLocaleDateString('fa-IR',{month:'short'})}</label></div>`}).join('')}</div><div class="legend"><span><i class="dot"></i>شهریه دریافتی</span><span><i class="dot" style="background:#d9e5dc"></i>هزینه‌های ثبت‌شده</span></div></div><div class="card"><div class="cardhead"><h3>نبض آموزشگاه</h3><span>◉</span></div><div class="row"><span>نیازمند تمدید شهریه</span><b>${money(db.students.filter(s=>!eligible(s)).length)} نفر</b></div><div class="row"><span>درخواست غیبت در انتظار</span><b>${money(db.absence_requests.filter(r=>r.status==='pending').length)}</b></div><div class="row"><span>کلاس‌های برگزارشده</span><b>${money(db.sessions.filter(s=>s.status==='completed').length)}</b></div><div class="row"><span>اساتید آموزشگاه</span><b>${money(db.teachers.length)} استاد</b></div><p class="sub">۲۰ دقیقه کلاس · ۴ جلسه در هر ترم</p></div></div><div class="card" style="margin-top:22px"><div class="cardhead"><h3>هنرجویان و وضعیت حضور</h3><a onclick="go('students')">مشاهده همه ←</a></div>${studentTable(db.students.slice(0,5))}</div>`},
students(){return title('هنرجویان','پرونده، زمان ثابت و وضعیت شهریه',btn('هنرجوی جدید','newStudent()'))+`<div class="card"><div class="toolbar"><input placeholder="جست‌وجوی نام یا شماره موبایل…" oninput="filterStudents(this.value)"></div><div id="studentlist">${studentTable(db.students)}</div></div>`},
teachers(){return title('اساتید آموزشگاه','سهم استاد: ۶۰٪ هر جلسه برگزارشده؛ ۳۰۰٬۰۰۰ تومان',admin?btn('ثبت تسویه استاد','newPayroll()'):'')+`<div class="teachergrid">${db.teachers.map(t=>{let sessions=db.sessions.filter(c=>c.status==='completed'&&db.students.find(s=>s.id===c.student_id)?.teacher_id===t.id);return `<div class="card"><div class="avatar">♫</div><h3>استاد ${esc(t.name)}</h3><p>${esc(t.subjects.join(' · '))}</p><div class="row"><span>جلسات برگزارشده</span><b>${money(sessions.length)}</b></div><div class="row"><span>دستمزد محاسبه‌شده</span><b>${money(sessions.reduce((a,c)=>a+Number(c.teacher_share),0))} تومان</b></div><div class="row"><span>تسویه ثبت‌شده</span><b>${money((db.payroll||[]).filter(p=>p.teacher_id===t.id).reduce((a,p)=>a+Number(p.amount),0))} تومان</b></div></div>`}).join('')}</div>`},
payments(){return title('شهریه و پرداخت‌ها','یک ترم ۲٬۰۰۰٬۰۰۰ تومان · دو ترم ۴٬۰۰۰٬۰۰۰ تومان',btn('ثبت دریافت شهریه','newPayment()'))+`<div class="card">${table(['هنرجو','تعداد ترم','مبلغ / تومان','شماره پیگیری','تاریخ'],confirmedPayments().map(p=>`<tr><td>${esc(full(db.students.find(s=>s.id===p.student_id)||{first_name:'',last_name:''}))}</td><td>${money(p.terms)}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td><td>${new Date(p.created_at).toLocaleDateString('fa-IR')}</td></tr>`))}</div><p class="sub">ثبت دریافت فقط توسط مدیر پس از بررسی واریز انجام می‌شود. درگاه آنلاین هنوز متصل نیست.</p>`},
expenses(){return title('هزینه‌های آموزشگاه','ثبت هزینه‌ها از ۱ آبان ۱۴۰۵؛ هزینه‌های قبل از این تاریخ در محاسبات نیستند',btn('ثبت هزینه','newExpense()'))+`<div class="card">${table(['دسته‌بندی','شرح هزینه','مبلغ / تومان','تاریخ'],db.expenses.map(p=>`<tr><td>${esc(p.category)}</td><td>${esc(p.description)}</td><td>${money(p.amount)}</td><td>${new Date(p.expense_date).toLocaleDateString('fa-IR')}</td></tr>`))}</div>`},
schedule(){return title('تقویم کلاس‌ها','زمان هنرجو ثابت است؛ هر جلسه ۲۰ دقیقه',office?btn('ایجاد ۴ جلسه ترم','generateTerm()'):'')+`<div class="card"><div class="toolbar"><button onclick="showProgram()">برنامه رشته‌ها در هفته</button></div>${table(['هنرجو','استاد','زمان','وضعیت','عملیات'],db.sessions.sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).map(c=>{const s=db.students.find(s=>s.id===c.student_id);return `<tr><td>${esc(s?full(s):'—')}</td><td>${s&&window.teacherInline?window.teacherInline(teacher(s.teacher_id)):esc(s?teacher(s.teacher_id):'—')}</td><td>${new Date(c.starts_at).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tehran'})}</td><td>${esc(statusLabel(c.status))}</td><td>${c.status==='scheduled'&&(office||role==='teacher')?`<button onclick="finishSession('${c.id}','completed')">ثبت حضور</button> <button onclick="finishSession('${c.id}','absent')">غیبت</button> <button onclick="cancelTeacher('${c.id}')">لغو استاد</button>`:''}${c.status==='teacher_cancelled'&&office?`<button onclick="makeup('${c.id}')">تعیین جبرانی</button>`:''}</td></tr>`}))}</div>`},
requests(){return title('غیبت و کلاس جبرانی','اعلام حداقل ۴ روز قبل؛ یک غیبت مجاز برای هر پرداخت دو ترم',btn('درخواست غیبت','requestAbsence()'))+`<div class="card">${table(['هنرجو','وضعیت درخواست','عملیات'],db.absence_requests.map(r=>`<tr><td>${esc(full(db.students.find(s=>s.id===r.student_id)||{first_name:'',last_name:''}))}</td><td>${esc(({pending:'در انتظار',approved:'تأییدشده',rejected:'ردشده'})[r.status])}</td><td>${office&&r.status==='pending'?`<button onclick="approveAbsence('${r.id}')">تأیید و حفظ اعتبار جلسه</button>`:'—'}</td></tr>`))}</div>`},
portal(){let s=db.students[0];return title('پرتال هنرجو','شهریه، اعتبار جلسات و اطلاعیه‌های شما')+(s?`<div class="hero"><div><h2>${esc(full(s))}، به پرتال خودت خوش آمدی</h2><p>${esc(s.subject)} · ${window.teacherInline?window.teacherInline(teacher(s.teacher_id)):'استاد '+esc(teacher(s.teacher_id))} · ${days[s.weekday]} ساعت ${esc(s.class_time.slice(0,5))}</p></div><span class="note">♫</span></div><div class="stats">${[['پرداخت ثبت‌شده',money(confirmedPayments().filter(p=>p.student_id===s.id).reduce((a,p)=>a+Number(p.amount),0))+' تومان'],['جلسات باقی‌مانده',money(credit(s))+' جلسه'],['بدهی انتقالی',money(s.opening_debt)+' تومان'],['وضعیت شرکت در کلاس',eligible(s)?'مجاز به حضور':'پرداخت الزامی']].map(a=>`<div class="card"><div class="sub">${a[0]}</div><h3>${a[1]}</h3></div>`).join('')}</div><div class="card"><h3>اطلاعیه‌های من</h3>${db.notices.filter(n=>!n.student_id||n.student_id===s.id).map(n=>`<div class="row">${esc(n.message)}</div>`).join('')||'<p class="sub">اطلاعیه‌ای ثبت نشده است</p>'}<p>برای پرداخت شهریه با دفتر هماهنگ کنید؛ اعتبار پس از تأیید واریز اضافه می‌شود.</p><button onclick="go('payments')">سوابق پرداخت</button> <button onclick="requestAbsence()">اعلام غیبت</button></div>`:'<div class="card empty">پرونده هنرجو هنوز به حساب شما متصل نشده است. با مدیر آموزشگاه هماهنگ کنید.</div>')},
import(){return title('شروع منظم، بدون از دست دادن سابقه','پروتکل انتقال هنرجویان فعلی به سامانه')+`<div class="card policy"><h3>۱. یک تاریخ شروع مشخص کنید</h3><p>جلسات قبل از تاریخ شروع را دوباره صورتحساب نکنید. برای هر هنرجو فقط اعتبار باقی‌مانده و بدهی قطعی را وارد کنید.</p><h3>۲. اطلاعات را از دفتر آموزشگاه تطبیق دهید</h3><p>نام و نام خانوادگی، نام پدر، کد ملی، موبایل، تاریخ تولد میلادی، تلفن و آدرس منزل، استاد، رشته، روز و ساعت ثابت، جلسات باقی‌مانده و بدهی انتقالی.</p><h3>۳. ابتدا پیش‌بررسی، سپس ثبت</h3><p>قالب JSON را دریافت و تکمیل کنید. پیش‌بررسی، کد ملی و تداخل استاد/زمان را کنترل می‌کند. ثبت نهایی گروهی است و در صورت خطا هیچ ردیفی ثبت نمی‌شود.</p><button onclick="downloadTemplate()">دریافت قالب انتقال JSON</button> <button onclick="document.getElementById('importfile').click()">انتخاب و پیش‌بررسی فایل</button><input id="importfile" type="file" accept="application/json" hidden onchange="previewImport(this)"><div id="importpreview"></div><h3>۴. اتصال حساب هنرجو</h3><p>ایمیل فعال هنرجو را در پرونده ثبت کنید. هنرجو با همان ایمیل ورود اول را انجام می‌دهد و پرونده به‌صورت خودکار به حساب تأییدشده متصل می‌شود. رمز را خود هنرجو تعیین می‌کند.</p><h3>۵. تأیید نهایی</h3><p>هنرجو مانده اعتبار و بدهی را تأیید کند؛ سپس جلسات آتی ایجاد شوند. پرداخت‌های قدیمی که در اعتبار انتقالی حساب شده‌اند دوباره ثبت نشوند.</p></div>`},
rules(){return title('قوانین و مقررات','نسخه اصلی به همراه استثنای اعلام‌شده مدیریت')+`<div class="grid"><div class="card policy">${[['حضور منظم','حضور به‌موقع در تمام جلسات الزامی است. هنرجو حداقل ۱۰ دقیقه قبل از شروع کلاس در آموزشگاه حاضر باشد. تأخیر قابل جبران نیست.'],['غیبت','غیبت بدون هماهنگی قبلی سوخت می‌شود؛ هزینه قابل استرداد نیست. در موارد خاص و اضطراری تصمیم با مدیریت است. استثنا: پرداخت هم‌زمان دو ترم، یک غیبت مجاز با اعلام حداقل ۴ روز قبل.'],['انضباط','احترام به اساتید، کارکنان و سایر هنرجویان، رعایت شئونات اخلاقی و فرهنگی الزامی است. سروصدا و بی‌نظمی ممنوع است.'],['حفظ اموال','مراقبت از سازها و تجهیزات الزامی است؛ خسارت ناشی از بی‌احتیاطی یا استفاده نادرست بر عهده هنرجو است.'],['شهریه','پرداخت پیش از شروع دوره الزامی است. پس از ثبت‌نام و آغاز کلاس شهریه قابل استرداد نیست.'],['تعطیلی کلاس‌ها','تعطیلات رسمی طبق برنامه اعلام‌شده برگزار یا جابه‌جا می‌شود. تغییر زمان فقط از سوی مدیریت اعلام می‌شود. غیبت استاد با کلاس جبرانی و حفظ اعتبار هنرجو پیگیری می‌شود.'],['تلفن همراه','استفاده در کلاس ممنوع، مگر با اجازه مدرس؛ تلفن در حالت سکوت باشد.'],['ضبط صدا و تصویر','فیلم‌برداری، عکاسی یا ضبط صدا بدون اجازه مدرس و مدیریت ممنوع است.'],['وسایل شخصی','آموزشگاه مسئول مفقودی یا آسیب وسایل شخصی نیست.'],['اطلاع‌رسانی','اطلاعیه‌ها از طریق تماس، پیامک یا شبکه‌های اجتماعی رسمی است؛ هنرجو موظف به پیگیری است.'],['حق تصمیم‌گیری','تصمیم نهایی موارد پیش‌بینی‌نشده بر عهده مدیریت آموزشگاه است.']].map((a,i)=>`<h3>${money(i+1)}. ${a[0]}</h3><p>${a[1]}</p>`).join('')}</div><div><img class="image" src="rules.webp" alt="متن اصلی قوانین آموزشگاه"><p class="sub">تصویر اصلی قوانین ارسالی آموزشگاه</p><button onclick="acceptRules()">قوانین را خوانده‌ام و می‌پذیرم</button></div></div>`}}
function studentTable(list){return table(['هنرجو','رشته و استاد','زمان ثابت','اعتبار','وضعیت','پرونده'],list.map(s=>`<tr><td><b>${esc(full(s))}</b></td><td>${esc(s.subject)} <span class="sub">· ${window.teacherInline?window.teacherInline(teacher(s.teacher_id)):esc(teacher(s.teacher_id))}</span></td><td>${days[s.weekday]} ${esc(s.class_time?.slice(0,5))}</td><td>${money(credit(s))} جلسه</td><td>${tag(s)}</td><td><button onclick="studentDetail('${s.id}')">مشاهده</button></td></tr>`))}function filterStudents(q){$('studentlist').innerHTML=studentTable(db.students.filter(s=>(full(s)+(s.mobile||'')).includes(q)))}
function field(name,label,type='text',options=null){return {name,label,type,options}}
function form(title,fields,submit){$('form').classList.remove('auth-form');$('form').querySelector('button[type="submit"]').textContent='ذخیره اطلاعات';$('mtitle').textContent=title;$('error').textContent='';$('fields').innerHTML=fields.map(f=>`<label>${esc(f.label)}${f.options?`<select name="${f.name}" required>${f.options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`:`<input name="${f.name}" type="${f.type==='date'?'text':f.type}" required ${f.type==='date'?'data-persian-date inputmode="numeric" dir="ltr" placeholder="۱۴۰۵/۰۸/۰۱" autocomplete="off"':''} ${f.type==='number'?'min="0" step="1"':''}>`}</label>`).join('');$('form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));for(const f of fields.filter(f=>f.type==='date'))data[f.name]=AcademyDates.iso(data[f.name]);await submit(data);modal.close();toast(token?'اطلاعات ثبت شد':'کد ورود درخواست شد');if(token)await reload()}catch(e){$('error').textContent=e.message}};modal.showModal()}
const studentsOpt=()=>db.students.map(s=>[s.id,full(s)]);
let authEmail='',authPending=null,authGeneration=0,authBusy=false,authSendAfter=0;
function authInput(name,label,type,extra=''){return `<label>${label}<input name="${name}" type="${type}" required ${extra}></label>`}
function authMessage(e){const m=String(e.message||'');if(/invalid.login|invalid.credentials/i.test(m))return 'ایمیل یا رمز عبور درست نیست. برای ورود اول یا بازیابی رمز از گزینه پایین استفاده کنید.';if(/expired|invalid.*token|otp/i.test(m))return 'کد نادرست یا منقضی شده است. آخرین کد ایمیل را وارد کنید.';if(/rate|too.many|seconds/i.test(m))return 'درخواست‌ها زیاد بوده؛ کمی صبر کنید و دوباره تلاش کنید.';return m||'ارتباط برقرار نشد؛ دوباره تلاش کنید.'}
function authScreen(title,html,label,submit){authGeneration++;const generation=authGeneration;$('mtitle').textContent=title;$('error').textContent='';$('error').setAttribute('role','alert');$('fields').innerHTML=html;$('form').classList.add('auth-form');const button=$('form').querySelector('button[type="submit"]');button.textContent=label;button.disabled=false;$('form').onsubmit=async e=>{e.preventDefault();if(authBusy)return;authBusy=true;button.disabled=true;$('error').textContent='';try{await submit(Object.fromEntries(new FormData(e.target)))}catch(err){if(generation===authGeneration)$('error').textContent=authMessage(err)}finally{authBusy=false;if(generation===authGeneration)button.disabled=false}};if(!modal.open)modal.showModal();$('fields').querySelector('input')?.focus()}
function login(){authPending=null;authScreen('ورود به پرتال',`<p class="auth-help">اگر قبلاً رمز ساخته‌اید، با ایمیل و رمز وارد شوید.</p>${authInput('email','ایمیل','email','autocomplete="username" dir="ltr"')}${authInput('password','رمز عبور','password','autocomplete="current-password" dir="ltr"')}<div class="auth-links"><button type="button" id="auth-first">ورود اول؛ ساخت رمز با کد ایمیل</button><button type="button" id="auth-forgot">رمزم را فراموش کرده‌ام</button></div>`,'ورود',async d=>{const a=await api('/auth/v1/token?grant_type=password','POST',{email:d.email.trim().toLowerCase(),password:d.password});await completeLogin(a)});if(authEmail)$('form').elements.email.value=authEmail;$('auth-first').onclick=()=>requestEmailCode(false);$('auth-forgot').onclick=()=>requestEmailCode(true)}
function requestEmailCode(recovery=false){authEmail=$('form').elements.email?.value.trim().toLowerCase()||authEmail;authScreen(recovery?'بازیابی رمز عبور':'فعال‌سازی ورود',`<p class="auth-help">کد تأیید را در همین صفحه وارد می‌کنید، سپس رمز خودتان را می‌سازید.</p>${authInput('email','ایمیل ثبت‌شده','email','autocomplete="email" dir="ltr"')}<button type="button" id="auth-password" class="auth-back">بازگشت به ورود با رمز</button>`,'ارسال کد تأیید',async d=>{const email=d.email.trim().toLowerCase();if(email===authEmail&&Date.now()<authSendAfter)throw Error('برای ارسال مجدد یک دقیقه صبر کنید.');await api('/auth/v1/otp','POST',{email,create_user:!recovery});authEmail=email;authSendAfter=Date.now()+60000;verifyLogin(email,recovery)});$('form').elements.email.value=authEmail;$('auth-password').onclick=login}
function normalizeCode(code){return code.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/\s/g,'')}
function verifyLogin(email,recovery=false){authScreen('تأیید کد ایمیل',`<p class="auth-help">کد ارسال‌شده به <b dir="ltr">${esc(email)}</b> را وارد کنید. پوشه هرزنامه را هم بررسی کنید.</p>${authInput('code','کد تأیید','text','autocomplete="one-time-code" inputmode="numeric" dir="ltr" maxlength="10" pattern="[0-9۰-۹٠-٩ ]{6,10}"')}<div class="auth-links"><button type="button" id="auth-resend">ارسال دوباره کد</button><button type="button" id="auth-change-email">تغییر ایمیل</button></div>`,'تأیید کد',async d=>{const code=normalizeCode(d.code);if(!/^\d{6,10}$/.test(code))throw Error('کد عددی ایمیل را کامل وارد کنید.');const a=await api('/auth/v1/verify','POST',{email,token:code,type:'email'});authPending=a;setOwnPassword(recovery)});$('auth-change-email').onclick=()=>requestEmailCode(recovery);$('auth-resend').onclick=async()=>{if(authBusy)return;if(Date.now()<authSendAfter){$('error').textContent='برای ارسال مجدد یک دقیقه صبر کنید.';return}authBusy=true;$('auth-resend').disabled=true;try{await api('/auth/v1/otp','POST',{email,create_user:!recovery});authSendAfter=Date.now()+60000;$('error').textContent='کد جدید درخواست شد؛ فقط آخرین کد را وارد کنید.'}catch(e){$('error').textContent=authMessage(e)}finally{authBusy=false;$('auth-resend').disabled=false}}}
function setOwnPassword(recovery=false){authScreen(recovery?'تعیین رمز جدید':'ساخت رمز عبور',`<p class="auth-help">ایمیل شما تأیید شد. برای ورودهای بعدی یک رمز اختصاصی با حداقل ۶ کاراکتر بسازید.</p><input type="hidden" name="email" value="${esc(authEmail)}" autocomplete="username">${authInput('password','رمز عبور جدید','password','autocomplete="new-password" minlength="6" maxlength="128" dir="ltr"')}${authInput('confirm','تکرار رمز عبور','password','autocomplete="new-password" minlength="6" maxlength="128" dir="ltr"')}<p class="auth-help">رمز را با کسی به اشتراک نگذارید.</p>`,'ثبت رمز و ورود',async d=>{if(d.password.length<6)throw Error('رمز باید حداقل ۶ کاراکتر باشد.');if(d.password!==d.confirm)throw Error('تکرار رمز با رمز عبور یکسان نیست.');if(!authPending?.access_token)throw Error('تأیید ایمیل منقضی شد؛ دوباره کد بگیرید.');const r=await fetch(URL+'/auth/v1/user',{method:'PUT',headers:{apikey:KEY,Authorization:'Bearer '+authPending.access_token,'Content-Type':'application/json'},body:JSON.stringify({password:d.password})});const result=await r.json();if(!r.ok)throw Error(result.msg||result.message||result.error_description||'ثبت رمز انجام نشد.');await completeLogin({...authPending,user:result})})}
async function completeLogin(a){if(!a?.access_token||!a.user?.id)throw Error('ورود کامل نشد. دوباره تلاش کنید.');token=a.access_token;uid=a.user.id;try{const staff=await api('/rest/v1/academy_staff?select=role,teacher_id&user_id=eq.'+uid);role=staff[0]?.role||'student';currentTeacherId=staff[0]?.teacher_id||null;admin=role==='admin';office=admin||role==='secretary';page=admin?'dashboard':role==='secretary'?'students':role==='teacher'?'schedule':'portal';await reload();$('notice').textContent='متصل به حساب واقعی · '+({admin:'مدیر',secretary:'منشی',teacher:'استاد',student:'هنرجو'})[role];$('loginbtn').textContent='خروج';$('loginbtn').onclick=async()=>{await api('/auth/v1/logout','POST').catch(()=>{});location.reload()};authPending=null;modal.close();toast('با موفقیت وارد شدید')}catch(e){token=null;uid=null;role='guest';admin=false;office=false;currentTeacherId=null;render();throw e}}
modal.addEventListener('close',()=>{authPending=null;authGeneration++;$('form').reset();$('form').classList.remove('auth-form')});

function newStudent(){if(!allowed())return;form('ثبت هنرجو و مانده افتتاحیه',[field('first_name','نام'),field('last_name','نام خانوادگی'),field('father_name','نام پدر'),field('national_id','کد ملی ۱۰ رقمی'),field('mobile','موبایل','tel'),field('email','ایمیل ورود هنرجو','email'),field('birth_date','تاریخ تولد (شمسی)','date'),field('home_phone','تلفن منزل','tel'),field('address','آدرس منزل'),field('teacher_id','استاد','text',db.teachers.map(t=>[t.id,t.name])),field('subject','رشته'),field('weekday','روز ثابت','text',days.map((d,i)=>[i,d])),field('class_time','ساعت ثابت','time'),field('opening_credit','جلسات باقی‌مانده قبلی','number'),field('opening_debt','بدهی قبلی / تومان','number')],async d=>{validateStudent(d);await api('/rest/v1/students','POST',d)})}
function validateStudent(s){if(!/^\d{10}$/.test(s.national_id))throw Error('کد ملی باید ۱۰ رقم انگلیسی باشد');if(!/^09\d{9}$/.test(s.mobile))throw Error('موبایل باید ۱۱ رقم و با 09 شروع شود');const t=db.teachers.find(t=>t.id===s.teacher_id);if(!t?.subjects.includes(s.subject))throw Error('رشته با فهرست رشته‌های استاد مطابقت ندارد');if(db.students.some(x=>x.teacher_id===s.teacher_id&&Number(x.weekday)===Number(s.weekday)&&Math.abs((Number(x.class_time.slice(0,2))*60+Number(x.class_time.slice(3,5)))-(Number(s.class_time.slice(0,2))*60+Number(s.class_time.slice(3,5))))<20))throw Error('این زمان با کلاس دیگری تداخل دارد')}
function studentDetail(id){const s=db.students.find(s=>s.id===id);if(!office){toast('دسترسی دفتر لازم است');return}form('اتصال حساب و تسویه بدهی انتقالی',[field('user_id','شناسه حساب Supabase Auth (UUID)'),field('opening_debt','مانده بدهی انتقالی / تومان','number')],async d=>{await api('/rest/v1/students?id=eq.'+id,'PATCH',d)});$('form').elements.opening_debt.value=s.opening_debt}
function newPayment(){if(!allowed())return;form('ثبت دریافت قطعی شهریه',[field('student_id','هنرجو','text',studentsOpt()),field('terms','تعداد ترم','text',[[1,'یک ترم · ۲ میلیون تومان'],[2,'دو ترم · ۴ میلیون تومان']]),field('reference','شماره پیگیری یکتا')],d=>api('/rest/v1/payments','POST',{...d,amount:Number(d.terms)*2000000}))}
function newExpense(){if(!admin){toast('فقط مدیر مجاز است');return;}form('ثبت هزینه آموزشگاه',[field('category','دسته','text',['اجاره','آب','برق','گاز','خرید متفرقه','سایر'].map(x=>[x,x])),field('description','شرح هزینه'),field('amount','مبلغ / تومان','number'),field('expense_date','تاریخ','date')],d=>{if(Number(d.amount)<=0)throw Error('مبلغ باید مثبت باشد');if(d.expense_date<AcademyDates.start)throw Error('هزینه‌ها فقط از ۱ آبان ۱۴۰۵ به بعد ثبت می‌شوند');return api('/rest/v1/expenses','POST',d)})}
function statusLabel(s){return ({scheduled:'برنامه‌ریزی شده',completed:'برگزار شده',absent:'غیبت غیرمجاز',teacher_cancelled:'لغو توسط استاد',excused:'غیبت مجاز'})[s]}
function generateTerm(){if(!allowed())return;form('ایجاد ۴ جلسه هفتگی',[field('student_id','هنرجو','text',studentsOpt()),field('date','تاریخ اولین جلسه (شمسی)','date')],async d=>{const s=db.students.find(s=>s.id===d.student_id),date=new Date(d.date+'T12:00:00Z');if(date.getUTCDay()!==Number(s.weekday))throw Error('روز انتخابی با روز ثابت هنرجو مطابقت ندارد');const rows=Array.from({length:4},(_,i)=>{const dt=new Date(date);dt.setUTCDate(dt.getUTCDate()+7*i);return {student_id:s.id,starts_at:dt.toISOString().slice(0,10)+'T'+s.class_time.slice(0,5)+':00+03:30'}});await api('/rest/v1/sessions','POST',rows)})}
async function finishSession(id,status){if(role!=='teacher'&&!allowed())return;try{if(role==='teacher'){await api('/rest/v1/rpc/mark_my_session','POST',{session_id:id,new_status:status});await reload();toast('وضعیت ثبت شد');return;}await api('/rest/v1/sessions?id=eq.'+id,'PATCH',{status});await reload();toast('وضعیت جلسه ثبت شد')}catch(e){toast(e.message)}}
async function cancelTeacher(id){if(role!=='teacher'&&!allowed())return;try{if(role==='teacher'){await api('/rest/v1/rpc/mark_my_session','POST',{session_id:id,new_status:'teacher_cancelled'});await reload();return;}const c=db.sessions.find(s=>s.id===id);await api('/rest/v1/sessions?id=eq.'+id,'PATCH',{status:'teacher_cancelled'});await api('/rest/v1/notices','POST',{student_id:c.student_id,message:'استاد در جلسه '+new Date(c.starts_at).toLocaleDateString('fa-IR')+' حضور ندارد. اعتبار محفوظ است؛ زمان جبرانی در پرتال اعلام می‌شود.'});await reload()}catch(e){toast(e.message)}}
function makeup(id){if(!allowed())return;form('تعیین جلسه جبرانی',[field('date','تاریخ جبرانی','date'),field('time','ساعت جبرانی','time')],async d=>{const c=db.sessions.find(s=>s.id===id);if(db.sessions.some(s=>s.makeup_for===id))throw Error('جبرانی این جلسه قبلاً ثبت شده');const starts=d.date+'T'+d.time+':00+03:30';await api('/rest/v1/sessions','POST',{student_id:c.student_id,starts_at:starts,makeup_for:id});await api('/rest/v1/notices','POST',{student_id:c.student_id,message:'جلسه جبرانی شما: '+new Date(starts).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'})})})}
function requestAbsence(){if(!token){toast('برای درخواست غیبت وارد حساب شوید');return}const sessions=db.sessions.filter(s=>s.status==='scheduled');form('اعلام غیبت حداقل ۴ روز قبل',[field('session_id','جلسه موردنظر','text',sessions.map(s=>[s.id,new Date(s.starts_at).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'})]))],d=>{const c=sessions.find(s=>s.id===d.session_id);return api('/rest/v1/absence_requests','POST',{session_id:c.id,student_id:c.student_id})})}
async function approveAbsence(id){if(!allowed())return;try{const r=db.absence_requests.find(r=>r.id===id);await api('/rest/v1/sessions?id=eq.'+r.session_id,'PATCH',{status:'excused'});await api('/rest/v1/absence_requests?id=eq.'+id,'PATCH',{status:'approved'});await reload()}catch(e){toast(e.message)}}
function showProgram(){ $('mtitle').textContent='برنامه هفتگی رشته‌ها';$('fields').innerHTML='<img class="image" src="program.webp" alt="برنامه رشته‌ها">';$('error').textContent='';$('form').onsubmit=e=>{e.preventDefault();modal.close()};modal.showModal()}
function downloadTemplate(){const data=[{first_name:'',last_name:'',father_name:'',national_id:'',mobile:'',email:'',opening_paid:0,balance_date:AcademyDates.show(AcademyDates.today()),opening_note:'انتقال از دفتر',birth_date:'۱۳۷۸/۱۰/۱۱',home_phone:'',address:'',teacher_id:db.teachers[0].id,subject:'ویولن',weekday:2,class_time:'16:00',opening_credit:0,opening_debt:0}];const a=document.createElement('a');a.href=URLcreate(data);a.download='hezardastan-import.json';a.click();setTimeout(()=>globalThis.URL.revokeObjectURL(a.href),1000)}function URLcreate(data){return globalThis.URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}))}
let importRows=[];async function previewImport(input){if(!allowed())return;try{const rows=JSON.parse(await input.files[0].text());if(!Array.isArray(rows)||!rows.length)throw Error('فایل باید آرایه غیرخالی باشد');const seen=new Set();for(const r of rows){for(const k of ['birth_date','balance_date'])if(r[k])r[k]=AcademyDates.iso(r[k]);validateStudent(r);if(seen.has(r.national_id))throw Error('کد ملی تکراری در فایل');seen.add(r.national_id)}importRows=rows;$('importpreview').textContent=money(rows.length)+' ردیف آماده بررسی نهایی. ';const b=document.createElement('button');b.textContent='تأیید و ثبت گروهی';b.onclick=async()=>{try{await api('/rest/v1/students','POST',importRows);importRows=[];await reload();toast('انتقال با موفقیت انجام شد')}catch(e){toast(e.message)}};$('importpreview').append(b)}catch(e){toast(e.message)}}
$('today').textContent=new Date().toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'});render();

function newPayroll(){if(!admin){toast('فقط مدیر مجاز است');return;}form('ثبت تسویه انجام‌شده استاد',[field('teacher_id','استاد','text',db.teachers.map(t=>[t.id,t.name])),field('amount','مبلغ / تومان','number'),field('reference','شماره پیگیری واریز')],d=>api('/rest/v1/payroll','POST',d))}

async function acceptRules(){if(!token){toast('ابتدا وارد حساب هنرجو شوید');return}try{await api('/rest/v1/rpc/accept_academy_rules','POST',{});await reload();toast('پذیرش قوانین با زمان ثبت شد')}catch(e){toast(e.message)}}

function assignStaff(){if(!admin){toast('فقط مدیر مجاز است');return}form('اختصاص نقش کاربر',[field('staff_email','ایمیل کاربر','email'),field('staff_role','نقش','text',[['teacher','استاد'],['secretary','منشی'],['admin','مدیر']]),field('staff_teacher','استاد مربوطه (فقط نقش استاد)','text',db.teachers.map(t=>[t.id,t.name]))],d=>api('/rest/v1/rpc/assign_academy_staff','POST',{...d,staff_teacher:d.staff_role==='teacher'?d.staff_teacher:null}))}
if(location.hash==='#rules'){page='rules';render()}
